   "refs": [
    {
     "book": "Ин",
     "chapter": 8,
     "verses": "1–11",
     "label": "Ин 8:1–11"
    }
   ],
   "summary": "Книжники и фарисеи приводят к Иисусу в храм женщину, взятую в прелюбодеянии, и спрашивают, побить ли её камнями по закону Моисея. Иисус пишет перстом на земле и отвечает: кто из вас без греха, первый брось на неё камень. Обвинители расходятся.",
   "retelling": "Иисус учил в Иерусалимском храме, вокруг собрался народ. Книжники и фарисеи привели женщину, взятую в прелюбодеянии, поставили её посреди и сказали: Учитель, эта женщина взята в момент преступления; Моисей в законе велел побивать таких камнями, а Ты что скажешь? Евангелист поясняет, что вопрос задан с умыслом — чтобы найти повод обвинить Иисуса.\n\nИисус, наклонившись низко, писал перстом на земле. Когда Его продолжали спрашивать, Он поднялся и сказал: кто из вас без греха, первый брось на неё камень. И снова стал писать на земле. Слушавшие, обличаемые совестью, начали уходить один за другим, начиная со старших. Остались Иисус и женщина. Он спросил, где её обвинители и осудил ли её кто-нибудь. Она ответила: никто, Господи. Иисус сказал: и Я не осуждаю тебя; иди и впредь не греши.\n\nЭпизода нет в древнейших рукописях Евангелия от Иоанна, а в некоторых списках он стоит в другом месте. Для живописи это значения не имело: сюжет стал одним из самых популярных в Венеции XVI века, в Нидерландах и позже в России.\n\nХудожники выбирают разные моменты. Чаще всего — само обвинение: тесная толпа мужчин, кто-то держит женщину за руку или указывает на неё, Христос спокоен и останавливает их жестом. Другой вариант — Христос, склонившийся к земле и пишущий; что именно Он писал, Евангелие не говорит, и некоторые художники вписывают в землю слова Его ответа. Женщину пишут с опущенными глазами, иногда с непокрытой головой и в сбившейся одежде — знак того, что её привели силой. Место действия — храм: колонны, ступени, алтарь или двор.",
   "quote": {
    "text": "Когда же продолжали спрашивать Его, Он, восклонившись, сказал им: кто из вас без греха, первый брось на неё камень.",
    "ref": "Ин 8:7"
   },
