    "text": "Предающий же Его дал им знак, сказав: Кого я поцелую, Тот и есть, возьмите Его. И, тотчас подойдя к Иисусу, сказал: радуйся, Равви! И поцеловал Его.",
    "ref": "Мф 26:48–49"
