   "synonyms": [
    "Столпотворение",
    "Смешение языков",
    "Башня до небес",
    "Нимрод"
   ],
   "refs": [
    {
     "book": "Быт",
     "chapter": 11,
     "verses": "1–9",
     "label": "Быт 11:1–9"
    }
   ],
   "summary": "Потомки Ноя, говорящие на одном языке, в земле Сеннаар решают построить город и башню «высотою до небес», чтобы сделать себе имя. Господь сходит посмотреть на постройку, смешивает их языки, и люди перестают понимать друг друга. Строительство остановлено, а люди рассеяны по земле.",
   "retelling": "Рассказ о Вавилонской башне занимает всего девять стихов в начале одиннадцатой главы Бытия. На всей земле был один язык и одно наречие. Двинувшись с востока, люди нашли равнину в земле Сеннаар и поселились там. Они договорились делать кирпичи и обжигать их огнём; кирпич служил им вместо камней, а земляная смола — вместо извести.\n\n«Построим себе город и башню, высотою до небес, и сделаем себе имя, прежде нежели рассеемся по лицу всей земли», — говорят они. Господь сходит посмотреть на город и башню и говорит, что раз они начали делать это, то не отстанут от задуманного. Он смешивает их язык так, чтобы один не понимал речи другого, и рассеивает их оттуда по всей земле. Они перестают строить город. Ему дано имя Вавилон, потому что там Господь «смешал» язык всей земли.\n\nНи царь, ни число этажей в тексте не упомянуты. Предводителем строительства традиция считала Нимрода, сильного зверолова, о царстве которого, начинавшемся с Вавилона, говорится в предыдущей главе; у Иосифа Флавия он прямо назван инициатором башни. Поэтому на нидерландских картинах на переднем плане часто стоит царь со свитой, осматривающий работу, а каменщики падают перед ним на колени.\n\nВ нидерландской живописи XVI века сюжет стал самостоятельным жанром. Питер Брейгель Старший задал образец: ярусная башня, вдохновлённая римским Колизеем, возводится по спирали, вокруг — гавань, леса, краны и подъёмные колёса. Его последователи, в том числе братья ван Валькенборх, повторяли эту схему десятки раз. Для зрителя того времени картина одновременно была энциклопедией строительной техники и притчей о гордыне и тщете больших замыслов.",
   "quote": {
    "text": "И сказали они: построим себе город и башню, высотою до небес, и сделаем себе имя, прежде нежели рассеемся по лицу всей земли.",
    "ref": "Быт 11:4"
   },
