   "summary": "Иисус приходит из Галилеи на Иордан, чтобы креститься у Иоанна. Иоанн сначала удерживает Его, затем уступает. Когда Иисус выходит из воды, открываются небеса, Дух Божий сходит, как голубь, и голос с неба называет Его возлюбленным Сыном.",
   "retelling": "Иоанн Креститель проповедовал в Иудейской пустыне и крестил приходивших к нему в реке Иордан, призывая к покаянию. Матфей описывает его подробно: одежда из верблюжьего волоса, кожаный пояс, пища — акриды и дикий мёд. Иоанн говорил, что за ним идёт Тот, Кто сильнее его и будет крестить Духом Святым и огнём.\n\nИисус пришёл из Галилеи на Иордан креститься. Иоанн удерживал Его: это ему самому нужно креститься от Иисуса. Иисус ответил, что так надлежит исполнить всякую правду, и Иоанн уступил. Крестившись, Иисус вышел из воды, и тогда открылись небеса, Иоанн увидел Духа Божия, сходящего, как голубь, и раздался голос с неба: «Сей есть Сын Мой возлюбленный». Тот же эпизод есть у Марка и Луки, а Иоанн Богослов передаёт его через свидетельство Крестителя.\n\nВ восточной традиции праздник называют Богоявлением: в одной сцене явлены Отец (голос), Сын и Дух (голубь). Поэтому на картинах вертикальная ось почти всегда одна и та же: сверху Бог Отец или раскрытое небо, ниже голубь, ещё ниже Христос в воде.\n\nИконография устойчива. Христос стоит по щиколотку или по колено в воде, обнажённый или в набедренной повязке, руки сложены или скрещены на груди. Иоанн — на берегу, во власянице, льёт воду из чаши или раковины либо возлагает руку на голову Христа. На берегу ангелы держат одежды Христа. На заднем плане часто раздеваются или ждут очереди другие крещаемые — напоминание о том, что к Иоанну шли толпы. Александр Иванов взял соседний момент — Иоанн указывает народу на идущего к нему Христа (Ин 1:29) — и превратил его в многофигурную сцену.",
   "quote": {
    "text": "И, крестившись, Иисус тотчас вышел из воды, — и се, отверзлись Ему небеса, и увидел Иоанн Духа Божия, Который сходил, как голубь, и ниспускался на Него. И се, глас с небес глаголющий: Сей есть Сын Мой возлюбленный, в Котором Моё благоволение.",
    "ref": "Мф 3:16–17"
   },
