   "summary": "Сыновья Адама и Евы приносят Богу дары: земледелец Каин — плоды земли, пастух Авель — первородных овец. Бог принимает жертву Авеля, а Каина нет. Каин уводит брата в поле и убивает его, а на вопрос Бога отвечает: «разве я сторож брату моему?» и уходит изгнанником.",
   "retelling": "Четвёртая глава Бытия рассказывает о первых детях Адама и Евы. Старший, Каин, становится земледельцем, младший, Авель, — пастухом овец. Спустя время оба приносят дар Господу: Каин — от плодов земли, Авель — от первородных стада и от тука их. Бог «призрел» на Авеля и его дар, а на Каина и его дар не призрел. Текст не объясняет почему, и толкователи веками спорили об этом.\n\nКаин сильно огорчается, и Бог предупреждает его: грех лежит у дверей, но ты господствуй над ним. Тогда Каин зовёт брата в поле и там убивает его. На вопрос «где Авель, брат твой?» он отвечает: «не знаю; разве я сторож брату моему?». Бог говорит, что голос крови брата вопиет от земли, и проклинает Каина: земля не будет давать ему силы, и он будет изгнанником и скитальцем. Каин боится, что его убьёт первый встречный, и Бог ставит на нём знамение, чтобы никто не поднял на него руку. Каин уходит в землю Нод, к востоку от Эдема.\n\nБиблия не называет орудие убийства. Художники давали Каину дубину, камень, мотыгу или ослиную челюсть — последний мотив пришёл из средневековой английской и северной традиции. Часто рядом стоят два жертвенника: над жертвой Авеля дым поднимается к небу, над жертвой Каина стелется по земле.\n\nВ живописи Возрождения и барокко сцена стала поводом для изображения борьбы двух обнажённых тел в резком ракурсе, особенно в плафонах, рассчитанных на взгляд снизу. В XIX веке интерес сместился к последствиям: Каин-изгнанник, уводящий своё племя в пустыню. Для христианской типологии Авель — невинная жертва, прообраз Христа.",
   "quote": {
    "text": "И сказал Каин Авелю, брату своему: [пойдём в поле]. И когда они были в поле, восстал Каин на Авеля, брата своего, и убил его.",
    "ref": "Быт 4:8"
   },
