   "summary": "Иисуса приводят на Голгофу и распинают между двумя разбойниками; над головой — надпись «Царь Иудейский». У креста стоят Мария, ученик, которого любил Иисус, и Мария Магдалина. В девятом часу Иисус умирает, тьма покрывает землю, завеса в храме раздирается.",
   "retelling": "Иисуса выводят из города на Голгофу — «лобное место». Нести крест заставляют встреченного по пути Симона Киринеянина. На Голгофе Ему дают пить уксус, смешанный с желчью, распинают и делят Его одежды, бросая жребий. Над головой прибивают надпись: «Иисус Назорей, Царь Иудейский» — по Иоанну, на еврейском, греческом и латинском. Отсюда латинская аббревиатура INRI. Вместе с Ним распинают двух разбойников, справа и слева.\n\nПроходящие мимо и первосвященники насмехаются: других спасал, а Себя не может спасти. С шестого часа до девятого тьма стоит по всей земле. Около девятого часа Иисус громко восклицает: «Или, Или! лама савахфани?» — Боже Мой, для чего Ты Меня оставил? Кто-то подаёт Ему губку с уксусом на трости. Иисус, снова возопив, испускает дух. Завеса в храме раздирается надвое, земля трясётся, камни расседаются, а сотник говорит: воистину Он был Сын Божий.\n\nИоанн добавляет сцену у креста: там стоят Мать Иисуса, сестра Её Мария Клеопова, Мария Магдалина и ученик, которого Он любил. Иисус поручает Мать ученику: Жено, се, сын Твой, — и ученику: се, Матерь твоя. Перед смертью Он говорит: совершилось. Чтобы тела не оставались на крестах в субботу, воинам велят перебить казнённым голени; Иисусу, уже умершему, голени не перебивают, но один из воинов пронзает Ему копьём рёбра, и истекают кровь и вода.\n\nИконография развивалась от многофигурных сцен с толпой, всадниками и воинами, разыгрывающими одежды, к сосредоточенным композициям из нескольких фигур. Устойчивые элементы: табличка INRI, череп у подножия креста (по преданию, череп Адама: Голгофу считали местом его погребения), Мария, иногда теряющая сознание, Иоанн в красном плаще, Магдалина с распущенными волосами, обнимающая подножие. В западной живописи с XIII века Христа обычно пишут прибитым тремя гвоздями, ноги наложены одна на другую; четыре гвоздя — следование более ранней традиции, как у Веласкеса.",
   "quote": {
    "text": "Иисус, увидев Матерь и ученика, тут стоящего, которого любил, говорит Матери Своей: Жено! се, сын Твой. Потом говорит ученику: се, Матерь твоя! И с этого времени ученик сей взял Её к себе.",
    "ref": "Ин 19:26–27"
   },
