   "summary": "Вечером после смерти Иисуса Иосиф из Аримафеи, тайный ученик, просит у Пилата тело и получает разрешение. Вместе с Никодимом, принёсшим смесь смирны и алоэ, он снимает тело с креста и обвивает пеленами с благовониями по иудейскому обычаю.",
   "retelling": "Евангелисты рассказывают о снятии с креста кратко. Наступал вечер пятницы, канун субботы, когда тела не должны были оставаться на крестах. Иосиф из Аримафеи — по Иоанну, ученик Иисуса, но тайный из страха перед иудеями; по Марку и Луке, почтенный член совета, не участвовавший в его решении, — пришёл к Пилату и попросил тело Иисуса. Марк добавляет, что Пилат удивился, что Иисус уже умер, и справился об этом у сотника.\n\nПилат позволил, и Иосиф снял тело. С ним пришёл и Никодим — тот, кто прежде приходил к Иисусу ночью, — и принёс около ста литр смеси смирны и алоэ. Они обвили тело пеленами с благовониями, как обыкновенно погребают иудеи. Женщины, пришедшие с Иисусом из Галилеи, смотрели, где и как полагали тело.\n\nЕвангелия не называют других участников, но в живописи сцена стала многофигурной. Иосиф Аримафейский и Никодим — двое пожилых мужчин в богатой одежде — на лестницах, приставленных к кресту, опускают тело, придерживая его полотном или белой плащаницей. Иоанн принимает тело снизу. Мария часто теряет сознание, её поддерживают женщины. Мария Магдалина — у ног Христа, рядом с ней сосуд с миром. На земле лежат клещи, вынутые гвозди, терновый венец.\n\nДля художника главная задача — показать безжизненное тяжёлое тело в движении, и решения бывают очень разными: от фризовой, почти скульптурной группы у Рогира ван дер Вейдена до бурной диагонали у Рубенса. В маньеризме сцена может обходиться вовсе без креста, становясь переходом к Оплакиванию и Положению во гроб. Снятие с креста часто занимало центр алтаря: тело, обращённое к зрителю, напоминало о причастии, которое совершалось на этом алтаре.",
   "quote": {
    "text": "После сего Иосиф из Аримафеи — ученик Иисуса, но тайный из страха от Иудеев, — просил Пилата, чтобы снять тело Иисуса; и Пилат позволил. Он пошёл и снял тело Иисуса.",
    "ref": "Ин 19:38"
   },
