   "summary": "Иосиф из Аримафеи и Никодим обвивают тело Иисуса плащаницей с благовониями и кладут в новый, высеченный в скале гроб в саду рядом с Голгофой. Ко входу приваливают большой камень. Мария Магдалина и другая Мария сидят напротив гроба.",
   "retelling": "Сразу после снятия с креста начинается погребение: приближалась суббота, и всё нужно было сделать до заката. Иосиф из Аримафеи взял тело, обвил его чистой плащаницей и положил в своём новом гробе, высеченном в скале. Иоанн уточняет, что гроб находился в саду недалеко от места распятия и в нём ещё никто не был положен, а Никодим принёс смесь смирны и алоэ; тело обвили пеленами с благовониями, как погребают иудеи.\n\nКо входу в гроб привалили большой камень. Мария Магдалина и другая Мария сидели напротив гроба и смотрели. На следующий день первосвященники попросили у Пилата стражу, опасаясь, что ученики украдут тело, и запечатали камень. Лука добавляет, что женщины, видевшие погребение, вернулись и приготовили благовония и масти, чтобы после субботы помазать тело.\n\nОплакивания в Евангелиях нет. Эта сцена создана церковной поэзией и мистическими текстами позднего Средневековья: момент между снятием с креста и погребением, когда близкие склоняются над телом. Отсюда несколько родственных сюжетов. «Оплакивание» — тело лежит на земле или на камне помазания, над ним плачут. «Пьета» — Мария держит Сына на коленях. «Положение во гроб» — тело несут к гробнице или опускают в саркофаг.\n\nВсе они узнаются по одному набору персонажей. Мария склоняется к лицу Сына, Иоанн в отчаянии раскидывает руки или закрывает лицо, Мария Магдалина — у ног Христа, иногда с сосудом мира. Иосиф Аримафейский и Никодим поддерживают тело за плечи и под колени. Гробница изображается как пещера в скале или, в итальянской традиции, как античный саркофаг. Отдельный вариант — мёртвый Христос один на каменной плите, почти без действия.",
   "quote": {
    "text": "и, взяв тело, Иосиф обвил его чистою плащаницею и положил его в новом своём гробе, который высек он в скале; и, привалив большой камень к двери гроба, удалился.",
    "ref": "Мф 27:59–60"
   },
