   "synonyms": [
    "Первородный грех",
    "Адам и Ева",
    "Искушение Евы",
    "Изгнание из рая",
    "Древо познания"
   ],
   "refs": [
    {
     "book": "Быт",
     "chapter": 3,
     "label": "Быт 3"
    }
   ],
   "summary": "Змей убеждает Еву, что плод с дерева познания добра и зла не принесёт смерти, а откроет глаза. Ева ест и даёт Адаму. Они видят свою наготу, прячутся от Бога, получают приговор и изгоняются из Эдема; путь к дереву жизни охраняет херувим с пламенным мечом.",
   "retelling": "Третья глава Бытия начинается со змея, который был «хитрее всех зверей полевых». Он спрашивает жену, правда ли Бог запретил есть от всякого дерева в саду. Она отвечает, что запрещён только плод дерева посреди сада, от которого можно умереть. Змей возражает: не умрёте, но откроются глаза ваши, и вы будете, как боги, знающие добро и зло. Жена видит, что дерево хорошо для пищи и приятно для глаз, ест плод и даёт мужу.\n\nУ обоих открываются глаза, они понимают, что наги, и сшивают себе опоясания из смоковных листьев. Услышав голос Господа Бога, ходящего в саду во время прохлады дня, Адам и жена прячутся среди деревьев. На вопрос Бога Адам указывает на жену, жена — на змея. Следует приговор: змей будет ходить на чреве и враждовать с семенем жены; жена будет рождать в болезни; земля будет проклята за человека, и он будет в поте лица есть хлеб, пока не возвратится в прах. Адам называет жену Евой, «матерью всех живущих». Бог делает им одежды кожаные и высылает из сада, а на востоке Эдема ставит херувима с пламенным обращающимся мечом.\n\nТекст не называет вид плода. Западная традиция сделала его яблоком — помогло созвучие латинских malum («зло») и malum («яблоко»); в северной живописи иногда пишут смокву или виноград. Змей с женской головой, частый в XV–XVI веках, восходит к средневековым комментариям, а не к Бытию.\n\nХудожники выбирают один из трёх моментов: искушение у дерева, стыд и укрытие или изгнание. Эта сцена — тема контраста: идеальные обнажённые тела Адама и Евы давали ренессансным мастерам законный повод писать антропометрию и пропорции, а в теологической программе алтарей грехопадение часто ставят рядом с Благовещением или Распятием как начало истории, которую они завершают.",
   "quote": {
    "text": "И увидела жена, что дерево хорошо для пищи, и что оно приятно для глаз и вожделенно, потому что даёт знание; и взяла плодов его и ела; и дала также мужу своему, и он ел.",
    "ref": "Быт 3:6"
   },
