   "summary": "Бог решает уничтожить развращённое человечество потопом и велит праведному Ною построить ковчег. В него входят семья Ноя и животные по паре. Вода сорок дней прибывает и покрывает горы. Ковчег останавливается на Араратских горах, голубь приносит масличный лист, а радуга становится знаком завета.",
   "retelling": "Шестая глава Бытия рассказывает, что Господь увидел, как велико развращение людей на земле, и раскаялся, что создал человека. Но Ной, «человек праведный и непорочный в роде своём», обрёл благодать в Его очах. Бог велит Ною сделать ковчег из дерева гофер, осмолить его внутри и снаружи и даёт точные размеры: триста локтей в длину, пятьдесят в ширину, тридцать в высоту, с окном, дверью и тремя ярусами.\n\nВ ковчег входят Ной, его жена, сыновья Сим, Хам и Иафет с жёнами, а также животные: по паре от всякой плоти, из чистых — по семи пар. Господь затворяет за Ноем дверь. Разверзаются источники великой бездны и окна небесные, дождь льёт сорок дней и сорок ночей, вода поднимает ковчег и покрывает все высокие горы. Всё живое на суше погибает.\n\nКогда вода начинает убывать, ковчег останавливается на горах Араратских. Ной выпускает ворона, а затем голубя; во второй раз голубь возвращается со свежим масличным листом во рту, в третий — уже не возвращается. Ной выходит из ковчега и приносит жертву, а Бог заключает с людьми завет больше не истреблять землю водами потопа; знамением завета становится радуга в облаке.\n\nЖивопись выбирает одну из двух стадий. Первая — сборы и вход животных в ковчег: для Бассано, Яна Брейгеля и американских мастеров XIX века это повод для каталога зверей и птиц, своего рода натуралистической энциклопедии. Вторая — сам потоп: гибнущие люди карабкаются на скалы, а ковчег виден вдали. Ковчег до эпохи Возрождения чаще пишут домом на лодке, позже — огромной баржей или ящиком. Голубь с масличной ветвью стал отдельным символом мира.",
   "quote": {
    "text": "и вошли к Ною в ковчег по паре от всякой плоти, в которой есть дух жизни; и вошедшие мужеский и женский пол всякой плоти вошли, как повелел ему Бог. И затворил Господь за ним.",
    "ref": "Быт 7:15–16"
   },
