   "synonyms": [
    "Иосиф Прекрасный",
    "Целомудрие Иосифа",
    "Искушение Иосифа",
    "Жена Пентефрия"
   ],
   "refs": [
    {
     "book": "Быт",
     "chapter": 39,
     "label": "Быт 39"
    }
   ],
   "summary": "Иосиф, проданный братьями в Египет, становится управляющим в доме Потифара, царедворца фараона. Жена хозяина день за днём склоняет его к связи; однажды она хватает его за одежду, и Иосиф убегает, оставив одежду у неё в руках. Она обвиняет его в попытке насилия, и Иосифа бросают в темницу.",
   "retelling": "Тридцать девятая глава Бытия продолжает историю Иосифа, любимого сына Иакова, которого братья продали измаильтянам. В Египте его покупает Потифар, царедворец фараона и начальник телохранителей. Господь благоволит Иосифу во всём, и хозяин поручает ему весь дом и всё имение, не зная при нём ничего, кроме хлеба, который ест.\n\nИосиф был красив станом и лицом, и жена господина обращает на него глаза и предлагает ему лечь с нею. Иосиф отказывается: хозяин доверил ему всё, кроме неё, и он не может сделать такое зло и согрешить пред Богом. Женщина повторяет предложение каждый день, а он не слушает её.\n\nОднажды Иосиф входит в дом по делам, когда никого из домашних там нет. Она хватает его за одежду и говорит: «ложись со мной». Он оставляет одежду в её руках и выбегает вон. Тогда она зовёт слуг и, показывая одежду, говорит, что муж привёл еврея ругаться над ними: он вошёл к ней, она закричала, и он убежал. Вечером ту же историю она рассказывает Потифару, и тот в гневе отдаёт Иосифа в темницу, где содержались узники царя. Но и там Господь с Иосифом: начальник темницы поручает ему всех заключённых, и с этого начинается путь к толкованию снов фараона и возвышению.\n\nТекст не называет имени жены Потифара — в позднейшей иудейской и исламской традиции её зовут Зулейха. На картинах сюжет почти всегда сосредоточен на одном мгновении: обнажённая или полуодетая женщина на ложе тянет на себя плащ, а юноша вырывается и отворачивается. Это позволяло художникам писать обнажённую натуру в «нравоучительном» сюжете о целомудрии. Реже изображают вторую сцену — жена показывает мужу одежду Иосифа как улику.",
   "quote": {
    "text": "она схватила его за одежду его и сказала: ложись со мной. Но он, оставив одежду свою в руках её, побежал и выбежал вон.",
    "ref": "Быт 39:12"
   },
