   "summary": "Лазарь из Вифании, брат Марфы и Марии, умирает. Иисус приходит, когда тот уже четыре дня в гробе, плачет, велит отвалить камень и громко зовёт: «Лазарь! иди вон». Умерший выходит, обвитый погребальными пеленами.",
   "retelling": "Лазарь жил в Вифании, недалеко от Иерусалима, вместе с сёстрами Марфой и Марией. Когда он заболел, сёстры послали сказать об этом Иисусу. Иисус ответил, что эта болезнь не к смерти, и пробыл ещё два дня там, где находился. Затем Он сказал ученикам, что Лазарь умер, и пошёл в Иудею, хотя там Его недавно хотели побить камнями.\n\nКогда Иисус пришёл, Лазарь уже четыре дня лежал во гробе. Марфа вышла навстречу и сказала: Господи, если бы Ты был здесь, не умер бы брат мой. В этом разговоре звучат слова «Я есмь воскресение и жизнь». Потом пришла Мария, пала к Его ногам и повторила слова сестры. Видя её плач и плач пришедших с ней иудеев, Иисус восскорбел духом и прослезился.\n\nГроб Лазаря — пещера, вход в которую закрыт камнем. Иисус велел отнять камень; Марфа возразила, что уже смердит, ведь прошло четыре дня. Камень отняли, Иисус помолился и воззвал громким голосом: Лазарь! иди вон. Умерший вышел, обвитый по рукам и ногам погребальными пеленами, лицо его было обвязано платком. Иисус сказал: развяжите его, пусть идёт. У Иоанна это последнее и самое значительное чудо перед Страстями: после него первосвященники решают убить Иисуса.\n\nЖивопись обычно выбирает кульминацию. Христос стоит с поднятой рукой — жест призыва или благословения. Лазарь выходит из скальной пещеры или поднимается из саркофага, всё ещё в пеленах; кто-то разматывает их или отодвигает плиту. Сёстры на коленях у ног Христа. Характерная деталь, идущая от слов Марфы, — зрители, зажимающие нос краем одежды. Воскрешение Лазаря читали как прообраз Воскресения Христа, поэтому сцену часто помещают в циклы Страстей рядом со Входом в Иерусалим.",
   "quote": {
    "text": "Сказав это, Он воззвал громким голосом: Лазарь! иди вон. И вышел умерший, обвитый по рукам и ногам погребальными пеленами, и лицо его обвязано было платком. Иисус говорит им: развяжите его, пусть идёт.",
    "ref": "Ин 11:43–44"
   },
