   "refs": [
    {
     "book": "Лк",
     "chapter": 15,
     "verses": "11–32",
     "label": "Лк 15:11–32"
    }
   ],
   "summary": "Притча Иисуса: младший сын требует у отца свою долю наследства, уходит в дальнюю страну и проматывает всё. Обнищав, он пасёт свиней и решает вернуться. Отец издали видит его, бежит навстречу и обнимает, а старший брат обижается на устроенный праздник.",
   "retelling": "Притчу рассказывает Иисус в ответ на ропот фарисеев и книжников: Он принимает грешников и ест с ними. В той же главе Луки — притчи о потерянной овце и потерянной драхме; притча о блудном сыне завершает этот ряд и самая подробная из трёх.\n\nУ человека было два сына. Младший попросил отдать ему причитающуюся часть имения, собрал всё и ушёл в дальнюю страну, где расточил имение, живя распутно. Когда там начался голод, он нанялся пасти свиней и рад был бы есть корм, который ели свиньи, но и того ему не давали. Придя в себя, он решил вернуться и сказать отцу: я согрешил и уже недостоин называться сыном твоим, прими меня в число наёмников.\n\nОтец увидел его издалека, сжалился, побежал, пал ему на шею и целовал его. Он велел слугам принести лучшую одежду, перстень и обувь и заколоть откормленного телёнка: этот сын был мёртв и ожил, пропадал и нашёлся. Старший сын, вернувшись с поля и услышав музыку, рассердился и не хотел войти: он столько лет служил отцу и ни разу не получил даже козлёнка для пира с друзьями. Отец ответил: ты всегда со мной, и всё моё твоё, а о брате надо радоваться. Чем закончился разговор, притча не сообщает.\n\nПритча дала живописи несколько самостоятельных сцен: уход из дома, кутёж в таверне, сын среди свиней, возвращение и пир. В Нидерландах XVI–XVII веков кутёж стал поводом для жанровой сцены «весёлого общества». Самая частая сцена — возвращение: сын, оборванный и босой, стоит на коленях перед отцом, тот обнимает его; рядом слуги несут одежду и ведут телёнка, а в стороне стоит старший брат.",
   "quote": {
    "text": "Встал и пошёл к отцу своему. И когда он был ещё далеко, увидел его отец его и сжалился; и, побежав, пал ему на шею и целовал его.",
    "ref": "Лк 15:20"
   },
