   "summary": "Филистимские владельцы подкупают Далиду, чтобы узнать тайну силы Самсона. Три раза он обманывает её, а в четвёртый признаётся: он назорей, и сила в нетронутых волосах. Далида усыпляет его на коленях и велит остричь семь кос. Ослабевшего Самсона хватают филистимляне и выкалывают ему глаза.",
   "retelling": "Самсон — последний из великих судей Израиля в Книге Судей. Ещё до его рождения ангел возвестил, что он будет назореем от чрева: бритва не должна касаться его головы. Его сила сверхъестественна — он голыми руками разрывает льва и убивает тысячу филистимлян ослиной челюстью.\n\nШестнадцатая глава рассказывает, как он полюбил женщину из долины Сорек по имени Далида. Владельцы филистимские обещают ей по тысяче сто сиклей серебра каждый, если она выведает, в чём его сила. Самсон трижды обманывает её: говорит, что ослабеет, если его свяжут семью сырыми тетивами, потом новыми верёвками, потом если вплести семь кос его головы в ткань. Каждый раз она произносит «Филистимляне идут на тебя, Самсон!», и он легко освобождается.\n\nДалида упрекает его в том, что он её не любит, и докучает ему каждый день, пока он не открывает правду: он назорей Божий, и если его остричь, сила отступит. Она усыпляет его на коленях, зовёт человека и велит остричь семь кос. Самсон просыпается без силы, филистимляне хватают его, выкалывают ему глаза, приводят в Газу, сковывают медными цепями, и он мелет в доме узников. Позже, когда волосы отрастают, его приводят на праздник в храм Дагона для потехи; Самсон упирается в два средних столба и обрушивает здание, погибая вместе с тысячами филистимлян.\n\nСинодальный перевод называет героиню Далидой; в искусствоведческой и бытовой традиции утвердилась форма Далила. На картинах чаще всего выбирают одно из трёх мгновений: стрижку спящего Самсона на коленях Далиды, пленение и ослепление. В эпоху Возрождения сюжет входил в серию «женских хитростей» вместе с Юдифью и Аристотелем с Филлидой. Барокко сделало его сценой ночного насилия, с резким светом и физически ощутимой болью.",
   "quote": {
    "text": "И усыпила его Далида на коленях своих, и призвала человека, и велела ему остричь семь кос головы его. И начал он ослабевать, и отступила от него сила его.",
    "ref": "Суд 16:19"
   },
