   "year": 1426,
   "date_label": "1426",
   "epoch": "early-renaissance",
   "museum": "capodimonte",
   "inventory": "Q 36",
   "details": [
    {
     "text": "Верхняя часть разобранного Пизанского полиптиха: голова Христа почти без шеи вжата в плечи — расчёт на взгляд снизу."
    },
    {
     "text": "Мария Магдалина в красном плаще бросилась к подножию креста спиной к зрителю, раскинув руки; по сторонам на золотом фоне — Мария и Иоанн."
    }
   ],
