   "year": 1881,
   "date_label": "1871–1891",
   "epoch": "art-19-20c",
   "museum": "gam-florence",
   "inventory": "Depositi GAM 5",
   "details": [
    {
     "text": "Зритель смотрит из глубины претории: Пилат и Христос стоят на балконе спиной к нам, перед ними внизу — толпа на залитой солнцем площади."
    },
    {
     "text": "Пилат в светлой тоге указывает рукой на Христа; Христос обнажён по пояс, в красной багрянице, руки связаны за спиной. Справа — жена Пилата со служанкой."
    }
   ],
