   "year": 1638,
   "date_label": "1638",
   "epoch": "classicism",
   "museum": "louvre",
   "inventory": "INV 7271",
   "details": [
    {
     "text": "Служанка и мужчина у кромки воды поднимают младенца из корзины, дочь фараона в жёлтом плаще указывает на него."
    },
    {
     "text": "Слева — бог Нила с рогом изобилия; за рекой — мост, башня и пирамида, фигуры выстроены фризом, как на античном рельефе."
    }
   ],
