   "title": "Бегство в Египет",
   "title_orig": {
    "text": "Die Flucht nach Ägypten",
    "lang": "de"
   },
   "artist": "adam-elsheimer",
   "year": 1609,
   "date_label": "1609",
   "epoch": "baroque",
   "museum": "alte-pinakothek",
   "inventory": "216",
   "details": [
    {
     "text": "Ночная сцена: над тёмным лесом — звёздное небо с Млечным Путём, полная луна отражается в воде."
    },
    {
     "text": "Фигуры маленькие: Иосиф держит факел, Мария с Младенцем едет на осле; вдали у костра — пастухи."
    }
   ],
