   "title": "Иосиф и жена Потифара",
   "title_orig": {
    "text": "José y la mujer de Putifar",
    "lang": "es"
   },
   "artist": "jacopo-tintoretto",
   "year": 1555,
   "date_label": "ок. 1555",
   "epoch": "mannerism",
   "museum": "prado",
   "inventory": "P000395",
   "details": [
    {
     "text": "Обнажённая жена Потифара раскинулась на постели под красным балдахином и обеими руками тянет к себе плащ Иосифа."
    },
    {
     "text": "Иосиф в тёмном камзоле рвётся прочь. Вытянутый формат и ракурс снизу объясняются тем, что это одно из полотен для плафона; картину для испанского короля приобрёл Веласкес."
    }
   ],
