   "title": "Юдифь",
   "title_orig": {
    "text": "Judith",
    "lang": "en"
   },
   "artist": "giorgione",
   "year": 1504,
   "date_label": "ок. 1504",
   "epoch": "high-renaissance",
   "museum": "hermitage",
   "inventory": "ГЭ-95",
   "details": [
    {
     "text": "Юдифь стоит в рост на фоне тихого пейзажа, опираясь на меч, и ставит обнажённую ногу на отрубленную голову Олоферна."
    },
    {
     "text": "Лицо спокойное и отрешённое, без следов насилия, — образ добродетели, попирающей порок. Доска, по-видимому, была дверцей шкафа; позже её подрезали по краям и перевели на холст."
    }
   ],
