   "date_label": "ок. 1620",
   "epoch": "baroque",
   "museum": "uffizi",
   "inventory": "1567",
   "details": [
    {
     "text": "Служанка всем весом прижимает Олоферна к ложу, а Юдифь, засучив рукава, мечом рассекает ему шею — обе женщины работают как одна сила."
    },
    {
     "text": "Кровь стекает по белым простыням; на руке Юдифи браслет с изображениями Артемиды-охотницы."
    }
   ],
