   "epoch": "baroque",
   "museum": "national-gallery-london",
   "inventory": "NG1375",
   "details": [
    {
     "text": "На переднем плане молодая кухарка толчёт в ступке чеснок, старуха за её спиной указывает на неё пальцем; на столе — рыба, яйца, перец."
    },
    {
     "text": "Евангельская сцена — справа вверху в проёме: окно, картина на стене или зеркало — исследователи спорят до сих пор."
    }
   ],
