   "inventory": "NG 1670",
   "details": [
    {
     "text": "Христос сидит в кресле и указывает на Марию, которая сидит у его ног, подперев голову рукой."
    },
    {
     "text": "Марфа стоит за ним с корзиной хлеба; это одна из немногих картин Вермеера на евангельский сюжет, написанная до его жанровых интерьеров."
    }
   ],
