   "date_label": "ок. 1668",
   "epoch": "baroque",
   "museum": "hermitage",
   "inventory": "ГЭ-742",
   "details": [
    {
     "text": "Сын в лохмотьях стоит на коленях спиной к зрителю, одна ступня босая, с другой спадает стоптанный башмак; отец кладёт ему руки на плечи."
    },
    {
     "text": "Справа стоит старший брат в красном плаще и молча смотрит; в полутьме видны другие свидетели."
    }
   ],
