   "epoch": "mannerism",
   "museum": "kunsthistorisches-museum",
   "inventory": "GG_1530",
   "details": [
    {
     "text": "Сусанна сидит у воды и разглядывает себя в зеркало, прислонённое к шпалере из роз; рядом лежат драгоценности, гребень и флаконы."
    },
    {
     "text": "Один старец подглядывает из-за конца шпалеры на переднем плане, второй виден в глубине сада — героиня их ещё не замечает."
    }
   ],
