   "date_label": "1610",
   "epoch": "baroque",
   "museum": "schloss-weissenstein",
   "inventory": "191",
   "details": [
    {
     "text": "Сусанна сидит на каменной скамье и отворачивается, вскинув руки, чтобы защититься; над стеной за ней склонились два старика."
    },
    {
     "text": "Один шепчет другому на ухо; фон — пустая каменная балюстрада и небо. Ранняя подписанная и датированная работа Артемизии."
    }
   ],
