   "museum": "mauritshuis",
   "inventory": "147",
   "details": [
    {
     "text": "Сусанна, полусогнувшись у воды, торопливо прикрывается и смотрит прямо на зрителя, будто застигнутая им самим."
    },
    {
     "text": "Голова одного из старцев едва различима в зелени позади неё — Рембрандт почти убирает их из картины."
    }
   ],
