   "lead": "Пять сюжетов от Благовещения до Крещения и восемнадцать картин XIV–XVII веков. На них видно, как золотой фон сменяется комнатой, пейзажем и ночным светом: событие, показанное вне времени, переходит в мир, знакомый зрителю, а символы прячутся в предметах быта.",
